<script setup>
import BrandIcon from '../components/BrandIcon.vue'
import {ref,reactive} from 'vue'
import {useRouter,useRoute} from 'vue-router'
import {api,setSession} from '../api'
const router=useRouter(),route=useRoute(),register=ref(false),busy=ref(false),error=ref(''),notice=ref('')
const form=reactive({student_no:'',password:'',email:'',nickname:'',confirm_password:''})
async function submit(){error.value='';notice.value='';busy.value=true;try{
  if(register.value){if(form.password!==form.confirm_password)throw new Error('两次输入的密码不一致');await api('/auth/register',{method:'POST',body:form});register.value=false;notice.value='注册成功，请使用学号登录';form.password='';form.confirm_password=''}
  else{setSession(await api('/auth/login',{method:'POST',body:{student_no:form.student_no,password:form.password}})); const next=route.query.redirect;router.replace(typeof next==='string'&&next.startsWith('/')&&!next.startsWith('//')?next:'/')}
}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><div class="auth-layout"><section class="auth-story"><div class="brand light"><BrandIcon /><span>校园二手交易平台</span></div><div class="auth-intro"><span class="intro-tag">校园 · 好物 · 分享</span><h1>发现所需<br>分享闲置</h1><div class="exchange-art" aria-hidden="true"><div class="exchange-tile tile-book"><svg viewBox="0 0 80 80" fill="none"><path d="M15 17h22v49H15zM37 17h28v49H37" stroke="currentColor" stroke-width="3"/><path d="M45 28h12M45 37h12M22 56h8" stroke="currentColor" stroke-width="3"/></svg></div><div class="exchange-tile tile-headphones"><svg viewBox="0 0 80 80" fill="none"><path d="M17 47V37a23 23 0 0146 0v10" stroke="currentColor" stroke-width="4"/><rect x="12" y="40" width="13" height="23" rx="6" stroke="currentColor" stroke-width="3"/><rect x="55" y="40" width="13" height="23" rx="6" stroke="currentColor" stroke-width="3"/></svg></div><span class="exchange-arrow">↗</span></div></div></section><section class="auth-form"><div class="auth-box"><h2>{{register?'注册账号':'欢迎回来'}}</h2><form @submit.prevent="submit"><label>学号<input v-model.trim="form.student_no" required minlength="4" maxlength="20" autocomplete="username" placeholder="请输入学号"></label><template v-if="register"><label>邮箱<input v-model.trim="form.email" type="email" required autocomplete="email"></label><label>昵称<input v-model.trim="form.nickname" required maxlength="20"></label></template><label>密码<input v-model="form.password" type="password" required minlength="6" maxlength="20" :autocomplete="register?'new-password':'current-password'" placeholder="6–20 位密码"></label><label v-if="register">确认密码<input v-model="form.confirm_password" type="password" required minlength="6" maxlength="20" autocomplete="new-password"></label><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="notice" role="status" class="success">{{notice}}</p><button class="primary wide" :disabled="busy">{{busy?'正在处理…':register?'创建账号':'登录 →'}}</button></form><p class="auth-switch">{{register?'已有账号？':'还没有账号？'}} <button class="text-button" @click="register=!register;error='';notice=''">{{register?'返回登录':'立即注册'}}</button></p></div></section></div></template>
